// === Tab: mySketch ===
class Particle {
    constructor(x, y, size, color, teleportSpeed) {
        this.position = createVector(x, y); // Position of the particle
        this.velocity = p5.Vector.random2D(); // Random initial velocity
        this.size = size; // Size of the particle
        this.color = color; // Color of the particle
        this.opacity = 255;
        this.fading = false; // Flag to indicate if the particle is fading
        this.targetX = x; // Target X position for teleportation
        this.targetY = y; // Target Y position for teleportation
        this.currentBox = null;
        this.targetBox = null;
        this.teleportPending = false; // New property to handle delayed teleportation
        this.teleportSpeed = teleportSpeed; // Speed of teleportation
    }

    update() {
        // Update the position based on velocity
        this.position.add(this.velocity);
    }

    display() {
        // Draw the particle
        noStroke();
        fill(red(this.color), green(this.color), blue(this.color), this.opacity);
        ellipse(this.position.x, this.position.y, this.size);
    }

    constrain(minX, minY, maxX, maxY) {
        if (this.position.x - this.size / 2 < minX || this.position.x + this.size / 2 > maxX) {
        this.velocity.x *= -1;
        }
        if (this.position.y - this.size / 2 < minY || this.position.y + this.size / 2 > maxY) {
        this.velocity.y *= -1;
        }
        this.position.x = constrain(this.position.x, minX + this.size / 2, maxX - this.size / 2);
        this.position.y = constrain(this.position.y, minY + this.size / 2, maxY - this.size / 2);
    }

    checkCollision(other) {
        let d = dist(this.position.x, this.position.y, other.position.x, other.position.y);
        if (d < (this.size + other.size) / 2) {
        // Simple elastic collision response: swap velocities
        let temp = this.velocity.copy();
        this.velocity = other.velocity.copy();
        other.velocity = temp;

        // Separate the particles slightly to prevent overlap sticking
        let overlap = (this.size + other.size) / 2 - d;
        let direction = p5.Vector.sub(this.position, other.position).normalize();
        this.position.add(direction.mult(overlap / 2));
        other.position.sub(direction.mult(overlap / 2));
        }
    }

    fadeAndTeleport(speed) {
        if (this.fading) {
            this.opacity -= speed;
            if (this.opacity <= 0) {
                this.opacity = 0;
                this.teleportPending = true;
                this.fading = false; // stop fading, but teleport will happen next frame
            }
        } else if (this.teleportPending) {
            this.position.x = this.targetX;
            this.position.y = this.targetY;
            this.currentBox = this.targetBox;
            this.opacity = 255;
            this.teleportPending = false; // teleportation is done
        }
    }
}

let cols, rows, boxWidth, boxHeight, boxColors;
let boxIndex;
let particles = [];
let frameCounter = 0;
let pendingBoxChange = false;

function setup() {
    let canvas = createCanvas(800, 800); // X, Bluesky and Threads

    // Create a 3x3 grid of boxes
    cols = 3;
    rows = 3;
    boxWidth = width / cols;
    boxHeight = height / rows;
    let palette = ["#AFCBDB", "#D8A7B1", "#AFCBDB", 
                "#D8A7B1", "#C8B8D1", "#D8A7B1",
                "#AFCBDB", "#D8A7B1", "#AFCBDB",];
    boxColors = [];
    for (let i = 0; i < cols * rows; i++) {
        boxColors.push(palette[i]);
    }

    // Select a random box
    boxIndex = floor(random(cols * rows));

    // Put 20 particles in the square in the box
    const mutedPastelPalette = [
        "#B8C4A9", // Muted Sage
        "#D8A7B1", // Dusty Rose
        "#C8B8D1", // Pale Mauve
        "#E4D6C5", // Warm Sand
        "#AFCBDB"  // Muted Sky Blue
      ];
    let boxX = (boxIndex % cols) * boxWidth;
    let boxY = floor(boxIndex / cols) * boxHeight;
    let boxSize = min(boxWidth, boxHeight) / 2;
    for (let i = 0; i < 20; i++) {
        let x = random(boxX + boxSize / 2, boxX + boxWidth - boxSize / 2);
        let y = random(boxY + boxSize / 2, boxY + boxHeight - boxSize / 2);
        let color = random(mutedPastelPalette);
        let p = new Particle(x, y, 10, color, random(1, 4));
        p.currentBox = boxIndex;
        particles.push(p);
    }
}

function draw() {
    background("#F6EEE3"); // Light beige background

    for (let i = 0; i < cols; i++) {
        for (let j = 0; j < rows; j++) {
            // draw a square half the size of the box and centered in the box
            var x = i * boxWidth;
            var y = j * boxHeight;
            let boxColor = boxColors[i * rows + j];
            fill(boxColor);
            stroke(0);
            strokeWeight(2);
            rect(x, y, boxWidth, boxHeight);
            //fill(255);
            stroke(0);
            strokeWeight(1);
            let squareSize = boxWidth / 2;
            let squareX = x + (boxWidth - squareSize) / 2;
            let squareY = y + (boxHeight - squareSize) / 2;
            fill(255);
            rect(squareX, squareY, squareSize, squareSize);
            let lightenedColor = color(boxColor);
            lightenedColor.setAlpha(25);
            fill(lightenedColor);
            rect(squareX, squareY, squareSize, squareSize);
        }
    }

    //draw a line from the vertices of the squares to the vertices of the boxes
    stroke(0);
    strokeWeight(2);
    for (let i = 0; i < cols; i++) {
        for (let j = 0; j < rows; j++) {
            var x = i * boxWidth;
            var y = j * boxHeight;
            var squareSize = boxWidth / 2;
            var squareX = x + (boxWidth - squareSize) / 2;
            var squareY = y + (boxHeight - squareSize) / 2;
            line(x, y, squareX, squareY);
            line(x + boxWidth, y, squareX + squareSize, squareY);
            line(x, y + boxHeight, squareX, squareY + squareSize);
            line(x + boxWidth, y + boxHeight, squareX + squareSize, squareY + squareSize);
        }
    }

    frameCounter++;
    if (frameCounter % 180 === 0) {
        pendingBoxChange = true;
        let previousBoxIndex = particles[0].currentBox;
        let newBoxIndex;
        do {
            newBoxIndex = floor(random(cols * rows));
        } while (newBoxIndex === previousBoxIndex);
        for (let i = 0; i < particles.length; i++) {
            particles[i].targetBox = newBoxIndex;
            particles[i].fading = true;
            var boxX = (newBoxIndex % cols) * boxWidth;
            var boxY = floor(newBoxIndex / cols) * boxHeight;
            var squareX = boxX + (boxWidth - boxWidth / 2) / 2;
            var squareY = boxY + (boxHeight - boxHeight / 2) / 2;
            particles[i].targetX = random(squareX + particles[i].size / 2, squareX + boxWidth / 2 - particles[i].size / 2);
            particles[i].targetY = random(squareY + particles[i].size / 2, squareY + boxHeight / 2 - particles[i].size / 2);
        }
    }

    var squareSize = boxWidth / 2;

    for (let i = 0; i < particles.length; i++) {
        var p = particles[i];
        p.fadeAndTeleport(p.teleportSpeed);
        p.update();
        var boxX = (p.currentBox % cols) * boxWidth;
        var boxY = floor(p.currentBox / cols) * boxHeight;
        var squareX = boxX + (boxWidth - squareSize) / 2;
        var squareY = boxY + (boxHeight - squareSize) / 2;
        p.constrain(squareX, squareY, squareX + squareSize, squareY + squareSize);
    }

    if (pendingBoxChange) {
        let allFaded = true;
        for (let i = 0; i < particles.length; i++) {
            if (particles[i].opacity > 0) {
                allFaded = false;
                break;
            }
        }
        if (allFaded) {
            for (let i = 0; i < particles.length; i++) {
                var p = particles[i];
                p.currentBox = p.targetBox;
                var boxX = (p.currentBox % cols) * boxWidth;
                var boxY = floor(p.currentBox / cols) * boxHeight;
                var squareX = boxX + (boxWidth - squareSize) / 2;
                var squareY = boxY + (boxHeight - squareSize) / 2;
                p.targetX = random(squareX + 5, squareX + squareSize - 5);
                p.targetY = random(squareY + 5, squareY + squareSize - 5);
            }
            pendingBoxChange = false;
        }
    }

    for (let i = 0; i < particles.length; i++) {
      for (let j = i + 1; j < particles.length; j++) {
        particles[i].checkCollision(particles[j]);
      }
    }

    // Draw particles
    for (let i = 0; i < particles.length; i++) {
        particles[i].display();
    }
}

